import hashlib
def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()[:16]
backup = {"file-a.txt": "alpha", "file-b.txt": "beta-changed", "file-c.txt": "gamma"}
manifest = {"file-a.txt": digest("alpha"), "file-b.txt": digest("beta"), "file-c.txt": digest("gamma")}
for name, expected in manifest.items():
    actual = digest(backup[name])
    print(name, "->", "VERIFIED" if actual == expected else "ALTERED, needs restore")
print("missing files:", [n for n in manifest if n not in backup])
print("RESULT manifest comparison names the altered file plainly")
